/* ============================================================
   🖤 IG 貼紙牆（IG Sticker）
   ------------------------------------------------------------
   黑底格線 + 白色圓角貼紙卡：貼文卡、對話泡泡、通知條、個人檔案卡。
   ① 換自己的素材：把下面的 none 換成圖片
      —— 點編輯框上方「＋ 插入圖片」選圖，會自動貼成 url('...')，
         把它填進對應那一行即可（存檔後自動落檔，離線也在）。
   ② 換文案：直接改引號裡的字。
   ============================================================ */
:root {
    /* ▼▼▼ 你的素材（換這幾行就行）▼▼▼ */
    --art-bg: none;            /* 整頁背景大圖（不放就用黑底格線） */
    --art-photo: none;         /* 月曆上方貼文卡的照片 */
    --art-photo-2: none;       /* 影集頁頂部橫幅照片 */
    --art-sticker: none;       /* 中間加號鈕的底圖（沒放圖時是白底愛心） */
    --quote: 'you + me';                       /* 貼文卡下方的字 */
    --quote-sub: 'cant stop thinking of you';  /* 日曆下方泡泡的字 */
    --quote-memo: 'you are my person';         /* 標題下方小泡泡的字 */
    /* ▲▲▲ 素材結束 ▲▲▲ */

    --ig-ink: #1c1c1e;
    --ig-ink-soft: #6f7175;
    --ig-paper: #ffffff;
    --ig-paper-2: #f2f2f4;
    --ig-heart: #9a9ba0;
    --ig-page: #45454e;              /* 頁面底色（深灰） */
    --ig-onpage: #f2f2f6;            /* 直接畫在頁底上的字 */
    --ig-onpage-soft: #adaeb6;
    --ig-line: rgba(255, 255, 255, 0.09);
    --ig-round: 24px;
    --ig-shadow: 0 8px 22px rgba(0, 0, 0, 0.30);
    --ig-font: 'Poppins', 'Helvetica Neue', 'PingFang TC', 'Noto Sans TC', system-ui, sans-serif;
    --ig-serif: Georgia, 'Times New Roman', 'Noto Serif TC', 'Songti TC', serif;
    /* 沒放照片時的佔位：淺灰底 + 一顆灰愛心 */
    --ig-heart-gray-svg: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%23c4c5ca'><path d='M12 21s-7.5-4.7-9.4-9A5.3 5.3 0 0 1 12 6.6 5.3 5.3 0 0 1 21.4 12c-1.9 4.3-9.4 9-9.4 9z'/></svg>");
    --ig-fill: var(--ig-heart-gray-svg) center / 44px no-repeat, #ececef;
    --ig-heart-svg: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M12 21s-7.5-4.7-9.4-9A5.3 5.3 0 0 1 12 6.6 5.3 5.3 0 0 1 21.4 12c-1.9 4.3-9.4 9-9.4 9z'/></svg>");
    --ig-actions-svg: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 88 24' fill='none' stroke='%23000' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M12 20s-7-4.4-8.7-8.4A4.9 4.9 0 0 1 12 6.4a4.9 4.9 0 0 1 8.7 5.2C19 15.6 12 20 12 20z'/><path d='M44 4a8 8 0 0 0-6.9 12l-1.1 4 4.2-1A8 8 0 1 0 44 4z'/><path d='M84 3 66 11l7 2 2 7z'/></svg>");

    /* ── 全局：黑底 + 淺格線 ── */
    --cal-font: var(--ig-font);
    --cal-page-bg:
        linear-gradient(var(--ig-line) 1px, transparent 1px) 0 0 / 100% 74px,
        linear-gradient(90deg, var(--ig-line) 1px, transparent 1px) 0 0 / 74px 100%,
        repeating-linear-gradient(45deg, rgba(255, 255, 255, 0.022) 0 2px, transparent 2px 4px),
        linear-gradient(180deg, #50505b 0%, #45454e 45%, #3b3b43 100%);
    --cal-page-bg-image: var(--art-bg);
    --cal-page-bg-size: cover;
    --cal-page-bg-position: center;
    --cal-page-padding: max(var(--nuo-safe-top), 20px) 18px 130px;
    --cal-ink: var(--ig-onpage);
    --cal-ink-muted: var(--ig-onpage-soft);
    --cal-accent: var(--ig-onpage);

    /* ── 頂欄：IG 個人頁式，白字大標＋限動圈頭像 ── */
    --cal-title-color: var(--ig-onpage);
    --cal-title-size: 1.9rem;
    --cal-title-weight: 700;
    --cal-title-letter-spacing: -0.5px;
    --cal-title-font: var(--ig-serif);
    --cal-topbar-gap: 8px;
    --cal-avatar-size: 44px;
    --cal-avatar-radius: 50%;
    --cal-avatar-border: 2px solid var(--ig-page);
    --cal-avatar-shadow: 0 0 0 2px #fff, 0 0 0 3.5px rgba(255, 255, 255, 0.35), 0 6px 14px rgba(0, 0, 0, 0.3);

    /* ── 星期列 ── */
    --cal-week-color: #b9bac0;
    --cal-week-size: 0.68rem;
    --cal-week-weight: 700;
    --cal-week-transform: uppercase;

    /* ── 日格：暗方塊，今天翻白 ── */
    --cal-grid-gap: 6px;
    --cal-grid-margin-bottom: 18px;
    --cal-day-bg: rgba(255, 255, 255, 0.10);
    --cal-day-radius: 14px;
    --cal-day-border: none;
    --cal-day-shadow: none;
    --cal-day-backdrop-filter: none;
    --cal-day-shine: transparent;
    --cal-day-width: 92%;
    --cal-day-height: 88%;
    --cal-daynum-color: #e4e4e8;
    --cal-daynum-size: 0.95rem;
    --cal-daynum-weight: 600;
    --cal-today-bg: var(--ig-paper);
    --cal-today-color: var(--ig-ink);
    --cal-today-radius: 14px;
    --cal-today-shadow: 0 6px 14px rgba(0, 0, 0, 0.22);
    --cal-selected-border: 1.5px solid rgba(255, 255, 255, 0.6);
    --cal-selected-transform: none;
    --cal-selected-shadow: none;
    --cal-dot-color: var(--ig-heart);

    /* ── 今日卡片：白貼紙 ── */
    --cal-card-bg: var(--ig-paper);
    --cal-card-radius: var(--ig-round);
    --cal-card-border: none;
    --cal-card-shadow: var(--ig-shadow);
    --cal-card-backdrop-filter: none;
    --cal-card-padding: 18px 18px 16px;
    --cal-card-title-color: var(--ig-ink);
    --cal-card-title-size: 1rem;
    --cal-card-title-weight: 700;
    --cal-item-radius: 16px;
    --cal-item-padding: 12px 14px;
    --cal-item-border: none;
    --cal-item-shadow: none;
    --cal-item-user-bg: var(--ig-paper-2);
    --cal-item-ai-bg: #ebebee;
    --cal-item-todo-bg: #e4e4e8;
    --cal-item-header-color: var(--ig-ink-soft);
    --cal-item-text-color: var(--ig-ink);

    /* ── 底欄：整條貼底暗色列（不是懸浮膠囊）── */
    --cal-nav-bg: rgba(58, 58, 66, 0.96);
    --cal-nav-radius: 0;
    --cal-nav-border: none;
    --cal-nav-shadow: 0 -1px 0 rgba(255, 255, 255, 0.10);
    --cal-nav-backdrop-filter: blur(14px);
    --cal-nav-min-height: 76px;
    --cal-nav-padding-top: 12px;
    --cal-nav-color: #9a9ba2;
    --cal-nav-active-color: var(--ig-onpage);
    --cal-nav-active-transform: none;
    --cal-nav-label-size: 0.6rem;
    --cal-nav-label-weight: 700;

    /* 加號鈕 → 白色圓角方塊愛心貼紙，角落一顆小加號 */
    --cal-fab-bg: var(--ig-paper);
    --cal-fab-bg-image: var(--art-sticker);
    --cal-fab-color: #ffffff;
    --cal-fab-size: 54px;
    --cal-fab-radius: 16px;
    --cal-fab-border: none;
    --cal-fab-shadow: 0 8px 18px rgba(0, 0, 0, 0.35);

    --cal-sticker-size: 17px;
    --cal-sticker-border: 2px solid var(--ig-page);
    --cal-sticker-marker-bg: #ffffff;
    --cal-sticker-marker-shadow: none;
    --cal-sticker-heart-bg: var(--ig-heart);
    --cal-sticker-heart-shadow: none;

    /* ── 彈層 ── */
    --cal-overlay-bg: rgba(12, 12, 15, 0.5);
    --cal-overlay-backdrop-filter: blur(6px);
    --cal-modal-bg: var(--ig-paper);
    --cal-modal-radius: 24px;
    --cal-modal-border: none;
    --cal-modal-shadow: 0 20px 50px rgba(0, 0, 0, 0.4);
    --cal-menu-bg: var(--ig-paper);
    --cal-menu-radius: 20px;
    --cal-menu-shadow: 0 16px 34px rgba(0, 0, 0, 0.36);
    --cal-menu-item-color: var(--ig-ink);
    --cal-vcal-bg: var(--ig-paper-2);
    --cal-vcal-border: none;
    --cal-vcal-label-color: var(--ig-ink);
    --cal-vcal-sub-color: var(--ig-ink-soft);
    --cal-tag-radius: 999px;
    --cal-tag-border: none;

    /* ── 行程表：頂部檔案卡＋白貼文卡 ── */
    --cal-section-title-color: var(--ig-onpage);
    --cal-section-title-size: 1.05rem;
    --cal-section-title-weight: 700;
    --cal-now-pill-bg: var(--ig-paper);
    --cal-now-pill-color: var(--ig-ink);
    --cal-now-pill-border: none;
    --cal-now-pill-radius: 999px;
    --cal-tl-line: linear-gradient(to bottom, transparent, rgba(255, 255, 255, 0.18) 8%, rgba(255, 255, 255, 0.18) 92%, transparent);
    --cal-tl-dot-bg: #ffffff;
    --cal-tl-dot-border: 2px solid var(--ig-page);
    --cal-char-card-bg: transparent;
    --cal-char-avatar-size: 64px;
    --cal-char-avatar-radius: 50%;
    --cal-char-avatar-border: 2px solid #ffffff;
    --cal-char-avatar-shadow: 0 6px 16px rgba(0, 0, 0, 0.32);
    --cal-tl-header-color: var(--ig-onpage);
    --cal-bubble-radius: 20px;
    --cal-bubble-border-color: transparent;
    --cal-bubble-shadow: var(--ig-shadow);
    --cal-bubble-title-color: var(--ig-ink);
    --cal-bubble-sub-color: var(--ig-ink-soft);
    --cal-timeline-ai-bg: transparent;
    --cal-timeline-user-bg: transparent;
    --cal-agenda-bg: var(--ig-paper);
    --cal-agenda-color: var(--ig-ink);
    --cal-agenda-radius: 20px;
    --cal-agenda-shadow: var(--ig-shadow);
    --cal-agenda-line-color: rgba(255, 255, 255, 0.18);
    --cal-agenda-dot-bg: #ffffff;
    --cal-agenda-dot-border: 2px solid var(--ig-page);
    --cal-stat-header-bg: var(--ig-paper);
    --cal-stat-header-radius: var(--ig-round);
    --cal-stat-header-backdrop-filter: none;
    --cal-stat-avatar-bg: var(--ig-paper-2);
    --cal-stat-avatar-size: 60px;
    --cal-stat-avatar-radius: 50%;
    --cal-stat-name-color: var(--ig-ink);
    --cal-stat-label-color: var(--ig-ink-soft);
    --cal-stat-bar-bg: #e6e6ea;
    --cal-stat-bar-fill: var(--ig-ink);

    /* ── 待辦抽屜 ── */
    --cal-todo-panel-bg: var(--ig-paper);
    --cal-todo-panel-radius: 28px 28px 0 0;
    --cal-todo-panel-shadow: 0 -10px 26px rgba(0, 0, 0, 0.32);
    --cal-todo-radius: 16px;
    --cal-todo-text-color: var(--ig-ink);
    --cal-todo-check-bg: #ffffff;
    --cal-todo-check-border: 2px solid rgba(0, 0, 0, 0.25);
    --cal-todo-check-radius: 50%;
    --cal-todo-check-color: var(--ig-ink);

    /* ── 共鳴影集：IG 貼文流 ── */
    --cal-memory-bg: transparent;
    --cal-memory-bg-image: none;
    --cal-memory-title-bg: var(--ig-paper);
    --cal-memory-title-color: var(--ig-ink);
    --cal-memory-title-border: none;
    --cal-memory-title-radius: 999px;
    --cal-memory-title-shadow: var(--ig-shadow);
    --cal-memory-title-rotate: none;
    --cal-report-bg: var(--ig-paper);
    --cal-report-border: none;
    --cal-report-radius: var(--ig-round);
    --cal-report-shadow: var(--ig-shadow);
    --cal-report-title-color: var(--ig-ink);
    --cal-polaroid-bg: var(--ig-paper);
    --cal-polaroid-border: none;
    --cal-polaroid-radius: 18px;
    --cal-polaroid-padding: 8px 8px 12px;
    --cal-polaroid-shadow: var(--ig-shadow);
    --cal-polaroid-img-bg: var(--ig-paper-2);
    --cal-polaroid-img-radius: 12px;
    --cal-polaroid-caption-color: var(--ig-ink);
    --cal-polaroid-caption-font: var(--ig-font);
    --cal-badge-name-color: var(--ig-onpage);
    --cal-badge-avatar-bg: #ffffff;
    --cal-badge-avatar-border: 2px solid #ffffff;
    --cal-letter-bg: var(--ig-paper);
    --cal-letter-border: none;
}

/* ================= 頂欄：IG 個人頁 ================= */
.nuo-cal-topbar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 10px;
    row-gap: 12px;
}

.nuo-cal-title-wrap {
    position: static;
    transform: none;
    justify-content: flex-start;
    margin-right: auto;
    min-width: 0;
    order: 2;
}

.nuo-cal-topbar .back-icon {
    order: 1;
    width: 34px;
    height: 34px;
    padding: 7px;
    box-sizing: border-box;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.14);
    color: var(--ig-onpage);
    flex-shrink: 0;
}

.nuo-cal-topbar .header-actions {
    order: 3;
}

/* 標題下方一整行：小愛心泡泡（love note） */
.nuo-cal-decor-topbar {
    display: block;
    order: 4;
    flex-basis: 100%;
    width: fit-content;
    max-width: 100%;
    box-sizing: border-box;
    position: relative;
    padding: 8px 16px 8px 34px;
    background: var(--ig-paper);
    color: var(--ig-ink);
    border-radius: 999px 999px 999px 6px;
    font-size: 0.74rem;
    font-weight: 600;
    box-shadow: var(--ig-shadow);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.nuo-cal-decor-topbar::before {
    content: var(--quote-memo);
}

.nuo-cal-decor-topbar::after {
    content: '';
    position: absolute;
    left: 13px;
    top: 50%;
    width: 14px;
    height: 14px;
    transform: translateY(-50%);
    background: var(--ig-heart);
    -webkit-mask: var(--ig-heart-svg) center / contain no-repeat;
    mask: var(--ig-heart-svg) center / contain no-repeat;
}

/* ================= 月視圖 ================= */
.nuo-cal-month {
    position: relative;
    z-index: 1;
}

.nuo-cal-cell[data-dow='0'] .day-number,
.nuo-cal-cell[data-dow='6'] .day-number {
    color: #b0b1b7;
}

/* ---- 星期列上方：IG 貼文卡（照片＋ ♡ ○ ➤ ＋一句話）---- */
.nuo-cal-decor-grid-top {
    display: block;
    position: relative;
    width: 100%;
    box-sizing: border-box;
    margin: 0 0 18px;
    padding: 8px 8px 12px;
    background: var(--ig-paper);
    border-radius: 20px;
    box-shadow: var(--ig-shadow);
    z-index: 1;
}

.nuo-cal-decor-grid-top::before {
    content: '';
    display: block;
    aspect-ratio: 16 / 9;
    border-radius: 14px;
    background-color: #ececef;
    background-image: var(--art-photo);
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
}

.nuo-cal-decor-grid-top::after {
    content: var(--quote);
    display: block;
    margin-top: 10px;
    padding: 0 6px 0 92px;
    min-height: 22px;
    line-height: 22px;
    font-size: 0.9rem;
    font-weight: 700;
    letter-spacing: -0.2px;
    color: var(--ig-ink);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    background: var(--ig-actions-svg) 6px center / 80px 22px no-repeat;
}

/* ---- 日曆下方：對話泡泡 ---- */
.nuo-cal-decor-grid-bottom {
    display: block;
    position: relative;
    margin: 0 0 18px auto;
    width: fit-content;
    max-width: 80%;
    box-sizing: border-box;
    padding: 12px 44px 12px 16px;
    background: var(--ig-paper);
    color: var(--ig-ink);
    border-radius: 22px 22px 6px 22px;
    font-size: 0.9rem;
    font-weight: 700;
    line-height: 1.35;
    box-shadow: var(--ig-shadow);
}

.nuo-cal-decor-grid-bottom::before {
    content: var(--quote-sub);
}

.nuo-cal-decor-grid-bottom::after {
    content: '';
    position: absolute;
    right: 14px;
    top: 50%;
    width: 20px;
    height: 20px;
    transform: translateY(-50%);
    background: var(--ig-heart);
    -webkit-mask: var(--ig-heart-svg) center / contain no-repeat;
    mask: var(--ig-heart-svg) center / contain no-repeat;
}

/* ---- 今日卡片上方：通知條 ---- */
.nuo-cal-decor-card-top {
    display: flex;
    align-items: center;
    gap: 8px;
    margin: 0 8px -10px;
    padding: 8px 14px 18px;
    background: #dcdce0;
    color: var(--ig-ink-soft);
    border-radius: 18px 18px 0 0;
    font-size: 0.66rem;
    font-weight: 700;
    letter-spacing: 0.5px;
    text-transform: uppercase;
}

.nuo-cal-decor-card-top::before {
    content: '';
    width: 13px;
    height: 13px;
    flex-shrink: 0;
    background: var(--ig-ink-soft);
    -webkit-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M12 3a6 6 0 0 0-6 6c0 4-1.5 5.5-1.5 5.5h15S18 13 18 9a6 6 0 0 0-6-6zM10 18a2 2 0 0 0 4 0z'/></svg>") center / contain no-repeat;
    mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M12 3a6 6 0 0 0-6 6c0 4-1.5 5.5-1.5 5.5h15S18 13 18 9a6 6 0 0 0-6-6zM10 18a2 2 0 0 0 4 0z'/></svg>") center / contain no-repeat;
}

.nuo-cal-decor-card-top::after {
    content: 'new notification';
}

/* ================= 兩個行程頁：頂部 IG 檔案卡 ================= */
.nuo-cal-timeline .user-stat-header {
    margin: max(var(--nuo-safe-top), 16px) 16px 18px;
    padding: 16px 18px;
    border: none;
    box-shadow: var(--ig-shadow);
}

.nuo-cal-timeline .stat-avatar-wrapper {
    padding: 2px;
    background: #fff;
    box-shadow: 0 0 0 2px var(--ig-ink), 0 0 0 4px #fff;
}

.nuo-cal-timeline .stat-name {
    font-size: 1.05rem;
    letter-spacing: -0.2px;
}

.nuo-cal-timeline .stat-row,
.nuo-cal-timeline .stat-row span {
    color: var(--ig-ink-soft) !important;
}

.nuo-cal-timeline .stat-label {
    background: var(--ig-paper-2) !important;
    color: var(--ig-ink-soft) !important;
}

/* 日期標題：淺字 + 淺色三角旗（畫在頁底上） */
.nuo-cal-timeline .section-title,
.nuo-cal-timeline .section-title > span {
    color: var(--ig-onpage) !important;
}

.nuo-cal-timeline .timeline-flag-icon svg path {
    fill: var(--ig-onpage);
}

.nuo-cal-timeline .timeline-flag-icon {
    margin-left: 0 !important;
}

.nuo-cal-timeline .timeline-current-time-indicator {
    margin-left: 0 !important;
}

/* 行程氣泡：白貼文卡，時間改成灰字（蓋掉每條行程自帶的彩色） */
.nuo-cal-timeline .timeline-bubble.modern-bubble,
.nuo-cal-timeline .agenda-bubble {
    background-color: var(--ig-paper);
    background-image: none;
}

.nuo-cal-timeline .agenda-time {
    color: var(--ig-ink-soft) !important;
    font-weight: 700;
    letter-spacing: 0.5px;
}

.nuo-cal-timeline .bubble-location > svg {
    color: var(--ig-heart);
}

.nuo-cal-timeline .nuo-cal-note {
    text-align: left !important;
    font-style: normal !important;
    color: var(--ig-ink-soft) !important;
    background: var(--ig-paper-2);
    border-top: none !important;
    border-radius: 12px;
    padding: 8px 10px !important;
    margin-top: 8px !important;
}

/* 待辦抽屜：把「📝」洗成灰階、標題深色 */
.nuo-cal-timeline .todo-section-card .section-title,
.nuo-cal-timeline .todo-section-card .section-title > span {
    color: var(--ig-ink) !important;
}

.nuo-cal-timeline .todo-header-row .section-icon {
    filter: grayscale(1);
}

.nuo-cal-timeline .todo-collapse-icon {
    color: var(--ig-ink-soft);
}

/* ================= 共鳴影集：IG 貼文流 ================= */
/* 頂部橫幅照片卡 */
.nuo-cal-decor-memory-top {
    display: block;
    position: relative;
    margin: max(var(--nuo-safe-top), 16px) 20px 0;
    padding: 8px;
    background: var(--ig-paper);
    border-radius: 20px;
    box-shadow: var(--ig-shadow);
    z-index: 1;
}

.nuo-cal-decor-memory-top::before {
    content: '';
    display: block;
    aspect-ratio: 16 / 7;
    border-radius: 12px;
    background-color: #ececef;
    background-image: var(--art-photo-2);
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
}

.nuo-cal-memory .memory-header {
    padding-top: 16px;
}

.nuo-cal-memory .memory-title {
    font-size: 1rem;
    padding: 8px 20px;
}

/* 心情報告卡：白色貼文卡，去掉膠帶，糯米糰轉灰階配黑白貼紙 */
.nuo-cal-memory .mochi-report-card {
    padding: 28px 22px 30px;
    margin-top: 8px;
}

.nuo-cal-memory .mochi-report-card::before {
    display: none;
}

.nuo-cal-memory .mochi-glow-ring {
    background: radial-gradient(circle, rgba(0, 0, 0, 0.06) 0%, rgba(0, 0, 0, 0) 70%);
    animation: none;
}

.nuo-cal-memory .mochi-main-visual {
    filter: grayscale(0.85) contrast(1.05);
}

.nuo-cal-memory .report-header,
.nuo-cal-memory .report-sparkle {
    color: var(--ig-ink);
}

.nuo-cal-memory .satisfaction-title {
    color: var(--ig-ink);
}

.nuo-cal-memory .satisfaction-desc {
    color: var(--ig-ink-soft);
}

/* 分區標題：白貼紙裡的深字 + 深色圖標 */
.nuo-cal-memory .section-title,
.nuo-cal-memory .section-icon-img {
    color: var(--ig-ink);
}

/* 拍立得 → IG 貼文卡：白框圓角、去膠帶、圖下一排 ♡ ○ ➤ */
.nuo-cal-memory .polaroid-item {
    transform: none !important;
}

.nuo-cal-memory .tape-strip {
    display: none;
}

.nuo-cal-memory .polaroid-image {
    margin-bottom: 8px;
}

.nuo-cal-memory .polaroid-caption {
    padding: 26px 4px 0;
    position: relative;
}

.nuo-cal-memory .polaroid-caption::before {
    content: '';
    position: absolute;
    left: 4px;
    top: 0;
    width: 66px;
    height: 18px;
    background: var(--ig-actions-svg) left center / 66px 18px no-repeat;
}

.nuo-cal-memory .caption-date {
    color: var(--ig-ink-soft);
    font-size: 0.68rem;
}

.nuo-cal-memory .caption-title {
    color: var(--ig-ink);
    font-size: 0.88rem;
}

.nuo-cal-memory .badge-name {
    color: var(--ig-ink);
}

/* 寄語：白色貼文卡、不歪、深色字 */
.nuo-cal-memory .message-letter-paper {
    transform: none !important;
    border-radius: 20px !important;
    border: none !important;
    background-image: none !important;
    box-shadow: var(--ig-shadow) !important;
}

.nuo-cal-memory .message-letter-paper div {
    color: var(--ig-ink) !important;
    font-family: var(--ig-font) !important;
}

.nuo-cal-memory .letter-content,
.nuo-cal-memory .signer-name {
    color: var(--ig-ink);
}

.nuo-cal-memory .envelope-overlay {
    border-radius: 20px !important;
}

/* ================= 底欄：整條暗色列，選中頁籤下方小白點 ================= */
.nuo-cal-nav-btn > svg {
    width: 22px;
    height: 22px;
    stroke-width: 1.9;
}

.nuo-cal-nav-btn span {
    letter-spacing: 0.6px;
}

.nuo-cal-nav-btn.active {
    position: relative;
}

.nuo-cal-nav-btn.active::after {
    content: '';
    position: absolute;
    left: 50%;
    bottom: -6px;
    width: 4px;
    height: 4px;
    border-radius: 50%;
    background: var(--ig-onpage);
    transform: translateX(-50%);
}

/* 加號鈕：白色圓角方塊 + 中央灰愛心，右下角一顆黑色小加號 */
.add-button {
    position: relative;
    margin-top: -34px;
    background-size: cover;
    background-position: center;
}

.add-button::before {
    content: '';
    position: absolute;
    inset: 0;
    margin: auto;
    width: 26px;
    height: 26px;
    background: var(--ig-heart);
    -webkit-mask: var(--ig-heart-svg) center / contain no-repeat;
    mask: var(--ig-heart-svg) center / contain no-repeat;
}

.add-button > svg {
    position: absolute;
    right: -6px;
    bottom: -6px;
    width: 12px;
    height: 12px;
    padding: 4px;
    box-sizing: content-box;
    border-radius: 50%;
    background: var(--ig-ink);
    color: #fff;
    stroke-width: 3;
    box-shadow: 0 0 0 2px var(--ig-page);
}

/* ================= 細節收口（照參考圖 4/5）================= */
/* 標題 / 分區標題用襯線展示字（參考圖 5 的 Special day / Check-in） */
.month-title,
.section-title,
.overlap-title-text,
.memory-title,
.report-header,
.stat-name,
.timeline-header-title {
    font-family: var(--ig-serif) !important;
}

/* 今日卡片：條目 emoji 洗成灰階、「Soon」黃字改灰 */
.overlap-item-header {
    font-family: var(--ig-serif);
}

.overlap-item-header > span:first-child,
.overlap-item-header::first-letter {
    filter: grayscale(1);
}

.overlap-item-content span[style*="f59e0b"] {
    color: var(--ig-ink-soft) !important;
    background: #e2e2e6;
    border-radius: 999px;
    padding: 1px 8px;
    font-weight: 700;
}

/* 行程頁：時間標籤淺字（原本粉紅） */
.nuo-cal-timeline .nuo-cal-time-label {
    color: var(--ig-onpage) !important;
    font-weight: 700;
}

.nuo-cal-timeline .timeline-marker-content {
    color: #d0d1d6;
}

/* 待辦抽屜：綠 / 黃卡全部改成淺灰貼紙卡，日期改灰膠囊，🔁 改灰 */
.nuo-cal-timeline .todo-card,
.nuo-cal-timeline .todo-card:nth-child(n) {
    background: var(--ig-paper-2) !important;
    border: none !important;
}

.nuo-cal-timeline .todo-card [style*="EC4899"],
.nuo-cal-timeline .todo-card [style*="ec4899"] {
    color: var(--ig-ink-soft) !important;
}

.nuo-cal-timeline .todo-text-col > div:not(.todo-text) {
    display: inline-block;
    background: #e2e2e6;
    border-radius: 999px;
    padding: 2px 9px;
}

.nuo-cal-timeline .todo-comment-box {
    background: #ffffff;
    border-radius: 12px;
    color: var(--ig-ink-soft);
}

/* 影集頂部：做成參考圖的「瀏覽器視窗」貼紙（三顆點 + 愛心） */
.nuo-cal-decor-memory-top {
    padding: 36px 8px 8px;
}

.nuo-cal-decor-memory-top::before {
    aspect-ratio: 16 / 6;
}

.nuo-cal-decor-memory-top::after {
    content: '';
    position: absolute;
    left: 0;
    right: 0;
    top: 0;
    height: 28px;
    border-radius: 20px 20px 0 0;
    background:
        radial-gradient(circle, #b9bac0 3px, transparent 3.5px) 16px center / 12px 12px no-repeat,
        radial-gradient(circle, #b9bac0 3px, transparent 3.5px) 28px center / 12px 12px no-repeat,
        radial-gradient(circle, #b9bac0 3px, transparent 3.5px) 40px center / 12px 12px no-repeat,
        var(--ig-heart-gray-svg) calc(100% - 12px) center / 14px no-repeat,
        var(--ig-paper-2);
}

/* 加號鈕：沒放圖時純白（愛心由 ::before 畫），放了圖就當貼紙底圖 */
.add-button {
    background-color: var(--ig-paper);
}

/* ================= IG 貼紙化：行程氣泡 / 待辦 / 影集（照參考圖貼紙表） ================= */
/* 膠帶條（you + me 那張）與貼紙共用 */
.nuo-cal-timeline .timeline-bubble.modern-bubble,
.nuo-cal-memory .mochi-report-card,
.nuo-cal-memory .message-letter-paper {
    overflow: visible;
}

.nuo-cal-timeline .timeline-bubble.modern-bubble::before,
.nuo-cal-memory .mochi-report-card::after {
    content: '';
    position: absolute;
    top: -10px;
    left: 50%;
    width: 84px;
    height: 22px;
    transform: translateX(-50%) rotate(-3deg);
    background: repeating-linear-gradient(-45deg, rgba(0, 0, 0, 0.05) 0 4px, transparent 4px 8px), rgba(225, 225, 230, 0.92);
    border-radius: 2px;
    z-index: 2;
    pointer-events: none;
}

/* 行程氣泡：白色對話泡泡（左下小尾巴）、標題襯線、時間灰膠囊、地點灰字、備註灰泡泡、底部 ♡ ○ ➤ */
.nuo-cal-timeline .timeline-bubble.modern-bubble {
    position: relative;
    border-radius: 22px 22px 22px 6px;
    margin: 16px 4px 18px;
}

.nuo-cal-timeline .timeline-bubble.modern-bubble::after {
    content: '';
    position: absolute;
    left: -6px;
    bottom: 0;
    width: 16px;
    height: 16px;
    background: var(--ig-paper);
    clip-path: polygon(100% 0, 100% 100%, 0 100%);
    border-radius: 0 0 0 4px;
}

.nuo-cal-timeline .bubble-content-inner {
    padding: 18px 16px 12px;
}

.nuo-cal-timeline .bubble-title {
    font-family: var(--ig-serif) !important;
    font-size: 1.05rem !important;
    letter-spacing: -0.2px;
}

.nuo-cal-timeline .bubble-location {
    color: var(--ig-ink-soft) !important;
}

.nuo-cal-timeline .agenda-time {
    display: inline-block;
    background: #e2e2e6;
    border-radius: 999px;
    padding: 3px 10px;
    font-size: 0.72rem !important;
    letter-spacing: 0.3px;
}

.nuo-cal-timeline .nuo-cal-note {
    position: relative;
    border-radius: 14px 14px 14px 4px;
    background: var(--ig-paper-2);
}

.nuo-cal-timeline .bubble-content-inner::after {
    content: '';
    display: block;
    width: 66px;
    height: 18px;
    margin-top: 10px;
    background: var(--ig-actions-svg) left center / 66px 18px no-repeat;
    opacity: 0.8;
}

/* 時間軸左側時間：白色小貼紙 */
.nuo-cal-timeline .nuo-cal-time-label {
    background: var(--ig-paper);
    color: var(--ig-ink) !important;
    border-radius: 999px;
    padding: 2px 8px;
    font-size: 0.7rem !important;
}

/* 檔案卡：右上三顆點（wildflower 那張） */
.nuo-cal-timeline .user-stat-header {
    position: relative;
}

.nuo-cal-timeline .user-stat-header::after {
    content: '';
    position: absolute;
    right: 16px;
    top: 12px;
    width: 26px;
    height: 6px;
    background:
        radial-gradient(circle, #b9bac0 2.5px, transparent 3px) 0 center / 10px 6px no-repeat,
        radial-gradient(circle, #b9bac0 2.5px, transparent 3px) 8px center / 10px 6px no-repeat,
        radial-gradient(circle, #b9bac0 2.5px, transparent 3px) 16px center / 10px 6px no-repeat;
    pointer-events: none;
}

/* 待辦卡：通知卡風（右下角一顆愛心） */
.nuo-cal-timeline .todo-card {
    position: relative;
    border-radius: 18px !important;
}

.nuo-cal-timeline .todo-card::after {
    content: '';
    position: absolute;
    right: 14px;
    bottom: 12px;
    width: 16px;
    height: 16px;
    background: var(--ig-heart);
    -webkit-mask: var(--ig-heart-svg) center / contain no-repeat;
    mask: var(--ig-heart-svg) center / contain no-repeat;
    pointer-events: none;
}

.nuo-cal-timeline .todo-text {
    font-family: var(--ig-serif);
}

/* ---- 影集 ---- */
/* 月份：love note 卡（愛心 + 文字 + now） */
.nuo-cal-memory .memory-title {
    position: relative;
    padding: 8px 52px 8px 34px;
    border-radius: 16px;
}

.nuo-cal-memory .memory-title::before {
    content: '';
    position: absolute;
    left: 14px;
    top: 50%;
    width: 14px;
    height: 14px;
    transform: translateY(-50%);
    background: var(--ig-heart);
    -webkit-mask: var(--ig-heart-svg) center / contain no-repeat;
    mask: var(--ig-heart-svg) center / contain no-repeat;
}

.nuo-cal-memory .memory-title::after {
    content: 'now';
    position: absolute;
    right: 14px;
    top: 50%;
    transform: translateY(-50%);
    font-family: var(--ig-font);
    font-size: 0.66rem;
    font-weight: 600;
    color: var(--ig-heart);
}

/* 分區標題 → 白色貼紙條（appreciation post 那張），右側愛心 */
.nuo-cal-memory .section-title {
    position: relative;
    background: var(--ig-paper);
    color: var(--ig-ink) !important;
    border-radius: 18px 18px 18px 6px;
    padding: 12px 44px 12px 16px;
    box-shadow: var(--ig-shadow);
    margin-bottom: 18px;
}

.nuo-cal-memory .section-title .section-icon-img {
    color: var(--ig-ink);
}

.nuo-cal-memory .section-title::after {
    content: '';
    position: absolute;
    right: 14px;
    top: 50%;
    width: 20px;
    height: 20px;
    transform: translateY(-50%);
    background: var(--ig-heart);
    -webkit-mask: var(--ig-heart-svg) center / contain no-repeat;
    mask: var(--ig-heart-svg) center / contain no-repeat;
}

/* 圖片診斷小鈕：塞在貼紙裡改灰 */
.nuo-cal-memory .section-title button {
    background: var(--ig-paper-2) !important;
    border: none !important;
    color: var(--ig-ink-soft) !important;
    margin-right: 28px;
}

/* 心情報告卡：膠帶在上（::after 已當膠帶），內文襯線 */
.nuo-cal-memory .mochi-report-card {
    position: relative;
    margin-top: 18px;
}

.nuo-cal-memory .satisfaction-title {
    font-family: var(--ig-serif);
}

/* 閃光時刻貼文卡：右下角一顆「+」圓鈕（deep talks 那張） */
.nuo-cal-memory .polaroid-item {
    position: relative;
    overflow: visible;
}

.nuo-cal-memory .polaroid-item::after {
    content: '';
    position: absolute;
    right: -6px;
    bottom: -6px;
    width: 26px;
    height: 26px;
    border-radius: 50%;
    background:
        linear-gradient(#fff, #fff) center / 10px 2px no-repeat,
        linear-gradient(#fff, #fff) center / 2px 10px no-repeat,
        #b9bac0;
    box-shadow: 0 0 0 3px var(--ig-page);
    pointer-events: none;
}

.nuo-cal-memory .caption-title {
    font-family: var(--ig-serif);
}

/* 成就：整組放進白貼紙卡，名字改深色 */
.nuo-cal-memory .achievement-list-grid {
    background: var(--ig-paper);
    border-radius: 20px;
    padding: 16px 8px;
    box-shadow: var(--ig-shadow);
}

.nuo-cal-memory .achievement-list-grid .badge-name {
    color: var(--ig-ink) !important;
}

/* 寄語：筆記本（just us 那張）：左側一排線圈 + 膠帶 */
.nuo-cal-memory .message-letter-paper {
    padding-left: 40px !important;
    border-radius: 12px 20px 20px 12px !important;
}

.nuo-cal-memory .message-letter-paper::before {
    content: '';
    position: absolute;
    left: 10px;
    top: 22px;
    bottom: 22px;
    width: 14px;
    background: repeating-radial-gradient(circle at 7px 7px, #c4c5ca 0 4px, transparent 4.5px 100%) 0 0 / 14px 22px repeat-y;
    pointer-events: none;
}

.nuo-cal-memory .message-letter-paper::after {
    content: '';
    position: absolute;
    top: -10px;
    right: 26px;
    width: 70px;
    height: 20px;
    transform: rotate(4deg);
    background: repeating-linear-gradient(-45deg, rgba(0, 0, 0, 0.05) 0 4px, transparent 4px 8px), rgba(225, 225, 230, 0.92);
    border-radius: 2px;
    pointer-events: none;
}

.nuo-cal-memory .envelope-overlay {
    background: var(--ig-paper) !important;
    color: var(--ig-ink);
}

.nuo-cal-memory .envelope-overlay div {
    color: var(--ig-ink) !important;
}

/* ================= 收口三：時間欄 / 檔案卡 / 底欄（更 IG） ================= */
/* 左側時間：白色細字，不做膠囊（做膠囊會被時間軸左邊界裁掉） */
.nuo-cal-timeline .nuo-cal-time-label {
    background: none !important;
    padding: 0 !important;
    left: -42px !important;
    width: 38px !important;
    text-align: right !important;
    color: var(--ig-onpage) !important;
    font-size: 0.66rem !important;
    font-weight: 700 !important;
    letter-spacing: 0.3px;
    white-space: nowrap;
}

/* 時間軸圓點：白心深框，像 IG 的已讀點 */
.nuo-cal-timeline .agenda-dot {
    background: #ffffff !important;
    border: 2px solid var(--ig-page) !important;
    box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.3);
}

/* ---- 檔案卡：IG 個人頁（限動漸層圈 + 分隔線 + follow / message 兩顆膠囊）---- */
.nuo-cal-timeline .user-stat-header {
    padding: 16px 18px 54px;
}

.nuo-cal-timeline .stat-avatar-wrapper {
    padding: 3px;
    background: #ffffff;
    box-shadow:
        0 0 0 2px var(--ig-ink),
        0 0 0 4px #ffffff,
        0 0 0 6px #d6d6db;
}

.nuo-cal-timeline .stat-name {
    font-size: 1.1rem;
    font-weight: 800;
}

/* 兩個統計（今日行程 / 今日待辦）改成 IG 數字欄的灰標籤 */
.nuo-cal-timeline .stat-row span {
    background: var(--ig-paper-2);
    border-radius: 999px;
    padding: 3px 10px;
    font-size: 0.72rem !important;
}

/* 卡片底部：分隔線 + follow / message 兩顆灰膠囊（純裝飾，照參考圖 wildflower 那張） */
.nuo-cal-timeline .user-stat-header::before {
    content: '';
    position: absolute;
    left: 18px;
    right: 18px;
    bottom: 12px;
    height: 34px;
    border-top: 1px solid #e6e6ea;
    background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 200 24'><rect x='0' y='0' width='94' height='24' rx='8' fill='%23dcdce2'/><rect x='102' y='0' width='94' height='24' rx='8' fill='%23f0f0f3'/><text x='47' y='16.5' font-family='Helvetica,Arial,sans-serif' font-size='10' font-weight='700' fill='%236f7175' text-anchor='middle'>follow</text><text x='149' y='16.5' font-family='Helvetica,Arial,sans-serif' font-size='10' font-weight='700' fill='%236f7175' text-anchor='middle'>message</text></svg>") 0 12px / 200px 24px no-repeat;
    pointer-events: none;
}

/* 心情糯米糰 → 圓形頭像鈕 */
.nuo-cal-timeline .mood-trigger {
    background: var(--ig-paper-2);
    border-radius: 50%;
    width: 52px !important;
    height: 52px !important;
    filter: grayscale(0.7);
}

/* 彩色 emoji 一律洗成灰階（IG 貼紙表只有黑白灰） */
.nuo-cal-timeline .stat-row span,
.nuo-cal-timeline .bubble-location,
.nuo-cal-timeline .todo-text-col > div:not(.todo-text),
.nuo-cal-memory .caption-date,
.nuo-cal-memory .report-header {
    filter: grayscale(1);
}

/* ---- 底欄：IG 風純黑細線列 ---- */
.nuo-cal-nav-btn {
    gap: 5px;
}

.nuo-cal-nav-btn > svg {
    width: 25px;
    height: 25px;
    stroke-width: 1.7;
}

.nuo-cal-nav-btn span {
    font-size: 0.52rem;
    letter-spacing: 1.4px;
    text-transform: uppercase;
    opacity: 0.75;
}

.nuo-cal-nav-btn.active span {
    opacity: 1;
}

.nuo-cal-nav-btn.active::after {
    bottom: -7px;
    width: 5px;
    height: 5px;
}

/* ================= 收口四：頭像橢圓 / 一日結束 / 底欄留白 ================= */
/* 檔案卡頭像：兩頁都用同一顆固定比例的直立橢圓（珠寶蛋面那種長橢圓，不是被擠扁的橫的） */
.nuo-cal-timeline .stat-avatar-wrapper {
    width: 38px;
    height: 52px;
    border-radius: 50%;
}

.nuo-cal-timeline .stat-avatar,
.nuo-cal-timeline .stat-avatar-fallback {
    border-radius: 50%;
    object-fit: cover;
}

/* 「一日結束」這類時間軸標記：改成白色小貼紙膠囊，emoji 洗灰 */
.nuo-cal-timeline .timeline-marker-content {
    opacity: 1 !important;
    background: var(--ig-paper) !important;
    color: var(--ig-ink) !important;
    border-radius: 999px;
    padding: 6px 14px !important;
    font-size: 0.72rem !important;
    font-weight: 700;
    letter-spacing: 0.3px;
    box-shadow: var(--ig-shadow);
    filter: grayscale(1);
}

.nuo-cal-timeline .marker-dot-user {
    background: #ffffff !important;
    border: 2px solid var(--ig-page) !important;
}

/* 時間軸尾端多留一點空，最後一條不會頂到底欄 */
.nuo-cal-timeline .user-agenda-list {
    padding-bottom: 18px;
}

/*⁣⁠‌‌‍​⁠‍‍‍‌​‌​​‌‌‌‍‌‍⁠⁠‌‍‌‌‌​‍‌‌‌‌​⁠⁠​‌‍‌⁠​⁠‍‌‍‌​​⁠‍​‌​‌⁠​‌‍‍‍⁠‌⁠⁣ =================================== */
/* 顶栏高度变量 */
/* =================================== */
:root{
  --new-top-bar-height:85px;
  --new-top-content-y:40px;
}

/* =================================== */
/* 底栏样式变量 */
/* =================================== */
:root{
  --input-top-space:3px;
  --bottom-lift-space:20px;

  --box-border-width:1.5px;
  --box-border-radius:5px;
  --box-right-space:66px;
  --box-left-space:-10px;
  --box-top-offset:7px;
  --box-bottom-offset:7px;

  --input-box-pull-left:-27px;
  --input-box-pull-right:-37px;
  --input-text-padding-left:10px;

  --right-btn-size:28px;
  --right-mic-size:18px;

  --typing-btn-bottom:1.5px;
}
/* 当底栏包含引用预览栏时，底部距离抬高 4px */
.input-area-custom:has(.input-reply-preview-bar) {
  padding-bottom: calc(var(--bottom-lift-space) + 4px) !important;
}
/* =================================== */
/* 全局调位置 */
/* =================================== */
:root{
  --wechat-title-x:35px;
  --wechat-title-y:5px;
  --btn-back-translate-x:0px;
  --btn-back-translate-y:3px;
  --btn-info-translate-x:0px;
  --btn-info-translate-y:5px;

  --unread-num-top:13px;
  --unread-num-left:18px;
  --unread-num-font-size:10px;
  --unread-num-font-weight:700;
  --unread-num-padding:0 7px;
  --unread-num-height:18px;

  --voice-btn-x:-13px;
  --voice-btn-y:-5px;
  --voice-btn-size:28px;

  --btn-mic-x:28px;
  --btn-mic-y:0px;
  --btn-sticker-x:26px;
  --btn-sticker-y:0px;
  --btn-ai-send-x:22px;
  --btn-ai-send-y:0px;

  --fake-sticker-x:26px;
  --fake-sticker-y:0px;
  --real-send-x:22px;
  --real-send-y:0px;

  --gen-plus-x:24px;
  --gen-icon-y:49.5%;
  --gen-sticker-x:-16px;
  --gen-sticker-y:50.5%;
  --gen-mic-x:-77px;
  --gen-mic-y:25.8px;
}

/* =================================== */
/* 全局日间模式 */
/* =================================== */
@media (prefers-color-scheme: light) {
  body {
    --chat-header-bg:#ededed;
    --chat-header-title-color:#000000;
    --wechat-icon-color:%23171717;

    --chat-header-unread-num-bg:#e0e0e0!important;
    --chat-header-unread-num-color:#151515!important;

    --input-area-bg:#f7f7f7;
    --box-bg-color:#ffffff;
    --box-border-color:#ffffff;
    --input-area-border-top: 1px solid #e7e7e7;

    --input-text-color:#222222;
    --input-caret-color:#07c160;
    --input-selection-bg:rgba(7,193,96,.25);
    --bubble-me-bg:#95EC69;
    --bubble-me-color:#000000;
    --bubble-them-bg:#FFFFFF;
    --bubble-them-color:#000000;

    --reply-detached-bg:rgba(242,242,242,.85);
    --reply-detached-border: none;
    --reply-detached-name-color:#888888;
    --reply-detached-text-color:#888888;

    --input-reply-bar-bg:#eaeaea;
    --input-reply-bar-border:1px solid #eaeaea;
    --input-reply-bar-name-color:#888888;
    --input-reply-bar-text-color:#888888;
    --input-reply-bar-close-color:#999999;
  }
  body .chat-message-list-custom{
    background-color:rgba(0,0,0,0)!important;
  }
}

/* =================================== */
/* 全局夜间模式 */
/* =================================== */
@media (prefers-color-scheme: dark) {
  body {
    --chat-header-bg:#111111;
    --chat-header-title-color:#e5e5e5;
    --wechat-icon-color:%23e5e5e5;

    --chat-header-unread-num-bg:#1E1E1E!important;
    --chat-header-unread-num-color:#FFF!important;

    --input-area-bg:#171717;
    --box-bg-color:#292929;
    --box-border-color:#292929;

    --input-text-color:#f0f0f0;
    --input-caret-color:#07c160;
    --input-selection-bg:rgba(7,193,96,.35);

    --bubble-me-bg:#3EB575;
    --bubble-me-color:#191919;
    --bubble-them-bg:#2A2A2C;
    --bubble-them-color:#eaeaea;

    --reply-detached-bg:rgba(29,29,29,.85);
    --reply-detached-border:1px solid #272727;
    --reply-detached-name-color:#999999;
    --reply-detached-text-color:#999999;

    --input-reply-bar-bg:#303030;
    --input-reply-bar-border:1px solid #303030;
    --input-reply-bar-name-color:#999999;
    --input-reply-bar-text-color:#999999;
    --input-reply-bar-close-color:#888888;

    --dark-icon-opacity:.8;
    --narration-bg: var(--sys-msg-bg) !important;
    --narration-color: var(--sys-msg-color) !important;
    --system-msg-bg: var(--sys-msg-bg) !important;
    --system-msg-color: var(--sys-msg-color) !important;
  }
  body .chat-message-list-custom{
    background-color:rgba(0,0,0,.7)!important;
  }

  body .chat-header,
  body .chat-header-custom,
  body .glass-header{
    background-color:#111111!important;
    background-image:linear-gradient(#111111,#111111)!important;
    background-size:cover!important;
    background-repeat:no-repeat!important;
    backdrop-filter:none!important;
    -webkit-backdrop-filter:none!important;
    box-shadow:none!important;
  }
/* 修复纯代码流夜间模式下的顶栏白边 */
  .chat-header,
  .chat-header-custom,
  .glass-header {
    border-bottom: none !important;
    box-shadow: none !important;
  }
}

/* =================================== */
/* 顶栏 */
/* =================================== */
.chat-header,
.chat-header-custom{
  height:var(--new-top-bar-height)!important;
  padding-top:var(--new-top-content-y)!important;
  box-sizing:border-box!important;
}
.header-avatar-container{display:none!important;}
.header-btn-phone,
.header-btn-video{opacity:0!important;}
.header-profile-section{
  flex:1!important;
  display:flex!important;
  justify-content:center!important;
  align-items:center!important;
}
.chat-header-title{
  transform:translate(var(--wechat-title-x),var(--wechat-title-y))!important;
  font-size:17px!important;
  font-weight:500!important;
  color:var(--chat-header-title-color)!important;
}

/* 顶栏返回 / 更多图标 */
.header-btn-back svg,
.header-btn-info svg{display:none!important;}
.header-btn-back::before{
  content:"";
  display:block;
  width:20px;
  height:22px;
  -webkit-mask-image:url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="black" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M15 20l-8-8 8-8"/></svg>');
  mask-image:url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="black" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M15 20l-8-8 8-8"/></svg>');
  -webkit-mask-size:contain;
  mask-size:contain;
  -webkit-mask-repeat:no-repeat;
  mask-repeat:no-repeat;
  -webkit-mask-position:center;
  mask-position:center;
  background-color:var(--chat-header-title-color)!important;
  transform:translate(var(--btn-back-translate-x),var(--btn-back-translate-y))!important;
}
.header-btn-info::before{
  content:"";
  display:block;
  width:24px;
  height:24px;
  -webkit-mask-image:url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="black"><circle cx="5" cy="12" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="19" cy="12" r="1.5"/></svg>');
  mask-image:url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="black"><circle cx="5" cy="12" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="19" cy="12" r="1.5"/></svg>');
  -webkit-mask-size:contain;
  mask-size:contain;
  -webkit-mask-repeat:no-repeat;
  mask-repeat:no-repeat;
  -webkit-mask-position:center;
  mask-position:center;
  background-color:var(--chat-header-title-color)!important;
  transform:translate(var(--btn-info-translate-x),var(--btn-info-translate-y))!important;
}

/* 顶栏未读 */
.nuo-chat-header-unread-dot{
  --chat-header-unread-size:0!important;
  display:none!important;
}
.nuo-chat-header-unread-num{
  --chat-header-unread-num-top:var(--unread-num-top)!important;
  --chat-header-unread-num-left:var(--unread-num-left)!important;
  --chat-header-unread-num-size:var(--unread-num-font-size)!important;
  --chat-header-unread-num-weight:var(--unread-num-font-weight)!important;
  --chat-header-unread-num-padding:var(--unread-num-padding)!important;
  --chat-header-unread-num-height:var(--unread-num-height)!important;
  --chat-header-unread-num-radius:999px!important;
  display:flex!important;
  align-items:center!important;
  justify-content:center!important;
  --chat-header-unread-num-border:none!important;
  --chat-header-unread-num-shadow:none!important;
}

/* 对方正在输入 */
.chat-detail-screen:has(.stop-btn-custom) .chat-header-title{
  color:transparent!important;
}
.chat-detail-screen:has(.stop-btn-custom) .chat-header-title::before{
  content:"对方正在输入...";
  position:absolute;
  left:50%;
  transform:translateX(-50%);
  color:var(--chat-header-title-color)!important;
  font-size:var(--chat-header-title-size)!important;
  font-weight:var(--font-weight)!important;
  white-space:nowrap;
}
.nuo-typing-indicator{display:none!important;}

/* =================================== */
/* 底栏 */
/* =================================== */
.input-area-custom{
  padding-top:var(--input-top-space)!important;
  padding-bottom:var(--bottom-lift-space)!important;
}
.input-action-bar-custom,
.input-action-bar-custom > *,
.input-action-bar-custom .input-box-custom,
.input-box-custom,
.input-box-custom:focus,
.input-box-custom:disabled,
.input-box-custom:-webkit-autofill,
.input-box-custom:-webkit-autofill:focus{
  background-color:transparent!important;
  background-image:none!important;
  background:transparent!important;
  border:none!important;
  box-shadow:none!important;
  outline:none!important;
  -webkit-box-shadow:none!important;
  -webkit-background-clip:unset!important;
}
.input-box-custom::-webkit-input-placeholder{
  color:transparent!important;
  font-size:0px!important;
  opacity:0!important;
  -webkit-text-fill-color:transparent!important;
  visibility:hidden!important;
}
.input-box-custom::placeholder{
  color:transparent!important;
  font-size:0px!important;
  opacity:0!important;
  -webkit-text-fill-color:transparent!important;
  visibility:hidden!important;
}

/* 底栏左侧语音图标 */
.input-btn-plus svg{display:none!important;}
.input-btn-plus::before{
  content:"";
  display:block;
  width:var(--voice-btn-size)!important;
  height:var(--voice-btn-size)!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/17ec3907-e615-4349-a269-9f716cf59489.png');
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
  transform:translate(var(--voice-btn-x),var(--voice-btn-y))!important;
}

/* 底栏幽灵线框 */
.input-action-bar-custom{
  position:relative!important;
  z-index:1!important;
}
.input-action-bar-custom::before{
  content:"";
  position:absolute;
  top:var(--box-top-offset)!important;
  bottom:var(--box-bottom-offset)!important;
  left:var(--box-left-space)!important;
  right:var(--box-right-space)!important;
  border:var(--box-border-width) solid var(--box-border-color)!important;
  border-radius:var(--box-border-radius)!important;
  background-color:var(--box-bg-color)!important;
  border-color:var(--box-border-color)!important;
  pointer-events:none!important;
  z-index:-1!important;
}

/* 底栏输入框 */
.input-box-custom,
.input-box-custom *,
.input-action-bar-custom .input-box-custom,
.input-action-bar-custom .input-box-custom *{
  color:var(--input-text-color)!important;
  -webkit-text-fill-color:var(--input-text-color)!important;
  caret-color:var(--input-caret-color)!important;
}
.input-box-custom{
  margin-left:var(--input-box-pull-left)!important;
  margin-right:var(--input-box-pull-right)!important;
  text-align:left!important;
  padding-left:var(--input-text-padding-left)!important;
  padding-right:10px!important;
clip-path: inset(var(--box-top-offset) 0 var(--box-bottom-offset) 0) !important;
}
.input-box-custom::selection,
.input-box-custom *::selection{
  background-color:var(--input-selection-bg)!important;
  color:var(--input-text-color)!important;
  -webkit-text-fill-color:var(--input-text-color)!important;
}
.input-box-custom::-moz-selection,
.input-box-custom *::-moz-selection{
  background-color:var(--input-selection-bg)!important;
  color:var(--input-text-color)!important;
}

/* 底栏右侧按键 */
.input-btn-mic svg,
.input-btn-sticker svg,
.input-btn-ai svg,
.send-btn-custom svg{display:none!important;}
.input-btn-mic{transform:translate(var(--btn-mic-x),var(--btn-mic-y))!important;}
.input-btn-sticker{transform:translate(var(--btn-sticker-x),var(--btn-sticker-y))!important;}
.input-btn-ai,
.send-btn-custom{transform:translate(var(--btn-ai-send-x),var(--btn-ai-send-y))!important;}
.input-btn-mic::before{
  content:"";
  display:block;
  width:var(--right-mic-size)!important;
  height:var(--right-mic-size)!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/59f469f5-0c70-43ce-ae1e-4c633e9a4e9a.png');
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
}
.input-btn-sticker::before{
  content:"";
  display:block;
  width:var(--right-btn-size)!important;
  height:var(--right-btn-size)!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/da835c40-d3c7-4462-ad4b-5c598284837b.png');
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
}
.input-btn-ai::before,
.send-btn-custom::before{
  content:"";
  display:block;
  width:var(--right-btn-size)!important;
  height:var(--right-btn-size)!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/4f7329f5-0fbc-4871-98ea-b2223db71efb.png');
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
}

/* 打字状态监听 */
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)){
  align-items:flex-end!important;
}
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-btn-plus,
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-btn-mic,
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-btn-sticker,
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-btn-ai,
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .send-btn-custom{
  margin-bottom:var(--typing-btn-bottom)!important;
}
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-btn-ai{
  pointer-events:none!important;
  transform:translate(var(--fake-sticker-x),var(--fake-sticker-y))!important;
}
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-btn-ai::before{
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/da835c40-d3c7-4462-ad4b-5c598284837b.png')!important;
}
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .send-btn-custom{
  transform:translate(var(--real-send-x),var(--real-send-y))!important;
}
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-box-custom{
  min-height:40px!important;
  padding-top:10px!important;
  padding-bottom:10px!important;
}

/* AI 生成时底栏伪装 */
.stop-btn-custom{
  background:transparent!important;
  box-shadow:none!important;
  color:transparent!important;
  position:relative!important;
}
.stop-btn-custom svg{display:none!important;}
.chat-detail-screen:has(.stop-btn-custom) .stop-btn-custom::before{
  content:"";
  display:block;
  width:var(--right-btn-size)!important;
  height:var(--right-btn-size)!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/bfefc490-ba9e-4552-9926-abbb5b5d7cbe.png')!important;
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
  position:absolute!important;
  top:var(--gen-icon-y)!important;
  left:var(--gen-plus-x)!important;
  transform:translateY(-50%)!important;
  pointer-events:none!important;
}
.chat-detail-screen:has(.stop-btn-custom) .stop-btn-custom::after{
  content:"";
  display:block;
  width:28px!important;
  height:28px!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/da835c40-d3c7-4462-ad4b-5c598284837b.png')!important;
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
  position:absolute!important;
  top:var(--gen-sticker-y)!important;
  left:var(--gen-sticker-x)!important;
  transform:translateY(-50%)!important;
  pointer-events:none!important;
}
.chat-detail-screen:has(.stop-btn-custom) .input-action-bar-custom::after{
  content:"";
  display:block;
  width:17.9px!important;
  height:17.9px!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/59f469f5-0c70-43ce-ae1e-4c633e9a4e9a.png')!important;
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
  position:absolute!important;
  top:var(--gen-mic-y)!important;
  right:calc(var(--gen-mic-x) * -1)!important;
  transform:translateY(-50%)!important;
  pointer-events:none!important;
  z-index:10!important;
}

/* 禁用左侧菜单键旋转 */
.input-btn-plus,
.input-btn-plus:active,
.input-btn-plus:focus,
.input-btn-plus[class*="open"],
.input-btn-plus[class*="active"],
.input-action-bar-custom:has(.more-options-popup) .input-btn-plus{
  transform:none!important;
  rotate:0deg!important;
  transition:none!important;
}

/* 夜间底栏防白线 */
@media (prefers-color-scheme: dark) {
  body .input-area-custom,
  body .input-area-custom > *,
  body .input-action-bar-custom{
    background-color:#1E1E1E!important;
    background-image:linear-gradient(#1E1E1E,#1E1E1E)!important;
    background-size:100% 100%!important;
    background-repeat:no-repeat!important;
    backdrop-filter:none!important;
    -webkit-backdrop-filter:none!important;
    box-shadow:none!important;
    border-top:none!important;
    border-top-color:transparent!important;
  }

  /* 夜间图标防刺眼 */
  body .input-btn-plus::before{
    filter:invert(1) opacity(var(--dark-icon-opacity))!important;
  }
  body .input-btn-mic::before,
  body .input-btn-sticker::before,
  body .input-btn-ai::before,
  body .send-btn-custom::before{
    filter:invert(1) opacity(var(--dark-icon-opacity))!important;
  }
  body .chat-detail-screen:has(.stop-btn-custom) .stop-btn-custom::before,
  body .chat-detail-screen:has(.stop-btn-custom) .stop-btn-custom::after,
  body .chat-detail-screen:has(.stop-btn-custom) .input-action-bar-custom::after{
    filter:invert(1) opacity(var(--dark-icon-opacity))!important;
  }
}

/* =================================== */
/* 气泡微信化 */
/* =================================== */
:root{
  --bubble-me-padding:8px 11px;
  --bubble-them-padding:8px 11px;
  --wechat-bubble-radius:4px;
  --bubble-tail-width:15.5px;
  --bubble-tail-height:15.5px;
  --bubble-tail-top:11px;
  --bubble-me-tail-right:-3px;
  --bubble-them-tail-left:-3px;
}
.bubble-me-custom,
.bubble-them-custom{
  border-radius:var(--wechat-bubble-radius)!important;
  position:relative!important;
  overflow:visible!important;
  box-shadow:none!important;
  border:none!important;
}
/* 我方气泡小角：纯 CSS 圆角菱形 */
.bubble-me-custom::before{
  content:"" !important;
  display:block !important;
  position:absolute !important;
  top:var(--bubble-tail-top)!important;
  right:var(--bubble-me-tail-right)!important;
  width:var(--bubble-tail-width)!important;
  height:var(--bubble-tail-height)!important;
  background-color:var(--bubble-me-bg)!important;
  pointer-events:none!important;
  border-radius: 2px !important;
  transform: rotate(45deg) !important;
  z-index: -1 !important; 
}
/* 对方气泡小角：纯 CSS 圆角菱形 */
.bubble-them-custom::before{
  content:"" !important;
  display:block !important;
  position:absolute !important;
  top:var(--bubble-tail-top)!important;
  left:var(--bubble-them-tail-left)!important;
  width:var(--bubble-tail-width)!important;
  height:var(--bubble-tail-height)!important;
